TLM.f("Sancti/09-10",{"officium":"S. Nicolai de Tolentino Confessoris","rule":["vide C5b;","9 lectiones"],"fallback":"Commune/C5b","from":{"Introitus":"Commune/C5b","Lectio":"Commune/C5b","Graduale":"Commune/C5b","GradualeP":"Commune/C5b","Tractus":"Commune/C5b","Evangelium":"Commune/C5b","Offertorium":"Commune/C5b","Secreta":"Commune/C5b","Communio":"Commune/C5b"},"sections":{"Introitus":[{"k":"ref","la":"Ps 91:13-14"},{"k":"text","la":"Justus ut palma florébit: sicut cedrus Líbani multiplicábitur: plantátus in domo Dómini: in átriis domus Dei nostri."},{"k":"ref","la":"Ps 91:2"},{"k":"text","la":"Bonum est confitéri Dómino: et psállere nómini tuo, Altíssime."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Justus ut palma florébit: sicut cedrus Líbani multiplicábitur: plantátus in domo Dómini: in átriis domus Dei nostri."}],"Oratio":[{"k":"text","la":"Adésto, Dómine, supplicatiónibus nostris quas in beáti Nicolái Confessóris tui solemnitáte deférimus: ut qui nostræ justítiæ fidúciam non habémus, ejus qui tibi plácuit, précibus adjuvémur."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Corínthios"},{"k":"ref","la":"1 Cor 4:9-14"},{"k":"text","la":"Fratres: Spectáculum facti sumus mundo et Angelis et homínibus. Nos stulti propter Christum, vos autem prudéntes in Christo: nos infírmi, vos autem fortes: vos nóbiles, nos autem ignóbiles. Usque in hanc horam et esurímus, et sitímus, et nudi sumus, et cólaphis cǽdimur, et instábiles sumus, et laborámus operántes mánibus nostris: maledícimur, et benedícimus: persecutiónem pátimur, et sustinémus: blasphemámur, et obsecrámus: tamquam purgaménta hujus mundi facti sumus, ómnium peripséma usque adhuc. Non ut confúndant vos, hæc scribo, sed ut fílios meos caríssimos móneo: in Christo Jesu, Dómino nostro."}],"Graduale":[{"k":"ref","la":"Ps 36:30-31"},{"k":"text","la":"Os justi meditábitur sapiéntiam, et lingua ejus loquétur judícium."},{"k":"text","la":"Lex Dei ejus in corde ipsíus: et non supplantabúntur gressus ejus. Allelúja, allelúja.","mark":"V"},{"k":"ref","la":"Ps 111:1"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja"},{"k":"ref","la":"Ps 111:1"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis. Allelúja"},{"k":"ref","la":"Osee 14:6"},{"k":"text","la":"Justus germinábit sicut lílium: et florébit in ætérnum ante Dóminum. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 36:30-31"},{"k":"text","la":"Os justi meditábitur sapiéntiam, et lingua ejus loquétur judícium."},{"k":"text","la":"Lex Dei ejus in corde ipsíus: et non supplantabúntur gressus ejus.","mark":"V"},{"k":"ref","la":"Ps 111:1-3"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis."},{"k":"text","la":"Potens in terra erit semen ejus: generátio rectórum benedicétur.","mark":"V"},{"k":"text","la":"Glória et divítiæ in domo ejus: et justítia ejus manet in sǽculum sǽculi.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 12:32-34"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Nolíte timére, pusíllus grex, quia complácuit Patri vestro dare vobis regnum. Véndite quæ possidétis, et date eleemósynam. Fácite vobis sácculos, qui non veteráscunt, thesáurum non deficiéntem in cœlis: quo fur non apprópiat, neque tínea corrúmpit. Ubi enim thesáurus vester est, ibi et cor vestrum erit."}],"Offertorium":[{"k":"ref","la":"Ps 20:2-3"},{"k":"text","la":"In virtúte tua, Dómine, lætábitur justus, et super salutáre tuum exsultábit veheménter: desidérium ánimæ ejus tribuísti ei. (Allelúja.)"}],"Secreta":[{"k":"text","la":"Præsta nobis, quǽsumus, omnípotens Deus: ut nostræ humilitátis oblátio et pro tuórum tibi grata sit honóre Sanctórum, et nos córpore páriter et mente puríficet."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Matt 19:28-29"},{"k":"text","la":"Amen, dico vobis: quod vos, qui reliquístis ómnia et secúti estis me, céntuplum accipiétis, et vitam ætérnam possidébitis. (Allelúja.)"}],"Postcommunio":[{"k":"text","la":"Quaésumus, omnípotens Deus: ut, qui caeléstia aliménta percépimus, intercedénte beáto Nicoláo Confessóre tuo, per haec contra ómnia advérsa muniámur."},{"k":"macro","name":"Per Dominum"}]},"hr":{"6b4668e2db0b0991":{"t":"Ps 91, 13-14, Ps 91, 2\n(Ps 91, 13-14) Kao palma cvjeta i kao libanski cedar raste pravednik zasađen u Gospodnjem domu, u trijemovima hrama Boga našega. (Ps 91, 2) Dobro je slaviti Gospodina, i pjevati tvojemu imenu, Svevišnji.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 91, 13-14) Kao palma cvjeta i kao libanski cedar raste pravednik zasađen u Gospodnjem domu, u trijemovima hrama Boga našega.","kn":"(Ps. 91, 13-14). Pravednik cvate kao paoma i raste poput libanonskog cedra, usađen u domu Gospodnjem, u trijemovima hrama Boga našega. (Ps. 91, 2) Dobro je slaviti Gospodina i pjevati Imenu Tvomu, Višnji! Slava Ocu ... Pravednik .. .","knRef":"Kniewald 1942, str. 474–475 (snimka 238) (OCR)"},"0d9350c4286d3517":{"t":"<i>Pomolimo se</i>.\nČuj, Gospodine, naše molbe, koje ti prinosimo na svetkovinu blaženoga Nikole, tvoga priznavaoca i daj da nama, koji se ne uzdamo u svoju pravednost, pomognu molitve njegove koji se tebi svidio.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Cuj, Gospodine, naše molbe, koje Ti (prinosimo o svetkovini blaženoga I., priznavaoca Tvoga i podaj, da nama, koji se ne uzdamo u svoju pravednost, pomognu molitve onoga, koji se Tebi svidio. Po G. n.","knRef":"Kniewald 1942, str. 816–817 (snimka 409) (OCR)"},"641c47c9ff3544c0":{"t":"1 Kor 4, 9-14\nČitanje Poslanice bl. Pavla apostola Korinćanima. Braćo! Svijet i anđeli i ljudi upiru u nas pogled. Mi smo kao ludi radi Krista, a vi mudri u Kristu; mi smo slabi, a vi jaki; vi plemeniti, a mi prezreni. Sve do sada, i gladujemo, i žeđamo, i goli smo, i ćuškaju nas, i nemamo trajna boravišta i mučimo se radom svojih ruku. Psuju nas, a mi blagoslivljamo, progone nas, a mi trpimo, kleveću nas, a mi molimo, postali smo kao smeće ovoga svijeta, kao izmet svih sve do sada. Ovoga ne pišem zato da vas postidim, nego da vas opomenem kao svoju predragu djecu: u Isusu Kristu, Gospodinu našemu.","kn":"Čitanje poslanice bi. Pavla apostola Korinćanima (I, 4, 9-14). Braćo! Svijet i anđeli i ljudi upiru u nas pogled. Mi smo kao lude radi Krista, a vi mudri u Kristu; mi smo slabi, a vi jaki; vi plemeniti, a ml prezreni. Sve do sada 1 gladujemo i žeđamo i goli smo i ćuškaju nas i nemamo trajna boravišta i mučimo se radom svojih ruku. Psuju nas, a mi blagoslivljemo, progone nas, a mi trpimo, kleveću nas, a mi molimo, postali smo kao smeće ovoga svijeta, kao izmet svih sve do sada. Ovoga ne pišem zato da vas postidim, nego da vas opomenem kao svoju predragu djecu u Isusu Kristu, Gospodinu našemu. /","knRef":"Kniewald 1942, str. 594–595 (snimka 298) (OCR)"},"6d9e364d27075ba3":{"t":"Ps 36, 30-31\nPravednikova usta raspravljaju o mudrosti i njegov jezik govori o pravdi. Zakon mu je Božji u srcu, i noge mu neće posrnuti.\n\nPs 111, 1\n<i>aleluja</i>, <i>aleluja</i>.\nBlago čovjeku koji se boji Gospodina i koji uživa u njegovim zapovijedima. <i>Aleluja</i>.","kn":"(Ps. 36, 30-31). Pravednikova usta govore mudrost i njegov jezik kazuje pravdu. Zakon je Božji u njegovu srcu i njegove noge ne ce posrnuti.\n\nAleluja, aleluja. (Ps. 111, 1.) Blago čovjeku, koji se boji Go.spodma, .koji žudi zapovijedi njegove, aleluja.","knRef":"Kniewald 1942, str. 540–541 (snimka 271) (OCR)"},"1cac10fd63222759":{"t":"Lk 12, 32-34\nSlijedi sveto Evanđelje po Luki. U ono vrijeme reče Isus svojim učenicima: Nemojte se bojati, malo stado, jer je vaš Otac odlučio dati vam kraljevstvo. Prodajte što imate i dajte milostinju. Načinite sebi torbe koje neće ostarjeti, neprolazno blago na nebu, kamo se ne približava lupež, niti izjeda moljac. Jer gdje je vaše blago, ondje će biti i vaše srce.","kn":"t Slijedi sv. evanđelje po Luki (12,32-34). U ono vrijeme reče Isus svojim učenicima: Nemojte se bojati, malo stado, jer je vaš Otac odlučio dati vam kraljevstvo. Prodajte, što imate i dajte milostinju. Načinite sebi kese, koje ne stare; neprolazno blago na nebu, kamo se ne približava tat niti izjeda moljac. Jer gdje je vaše blago, ondje će biti i vaše srce.","knRef":"Kniewald 1942, str. 818–819 (snimka 410) (OCR)"},"4e296f3326e0e479":{"t":"Ps 20, 2-3\nU jakosti tvojoj, Gospodine, raduje se pravednik i kliče radi tvoga spasenja, jer si mu ispunio želju srca njegova.","kn":"(Ps. 20, 2-'3). U kreposti Tvojoj Gospodine, raduje se pravednik i kliče nad spasenjem Tvojim, jer si mu ispunio želju duše njegove.","knRef":"Kniewald 1942, str. 818–819 (snimka 410) (OCR)"},"1e8de8be36cd864e":{"t":"Daj nam, molimo, svemogući Bože, da naš ponizni prinos bude tebi drag zbog časti tvojih svetih,i neka očisti naše tijelo i dušu.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Podaj nam, molimo, svemogući Bože, da prinos naše smjernostl bude i Tebi mio radi časti svetaca, i nas da očisti zajedno na tijelu i na duši. Po Gospodinu ...","knRef":"Kniewald 1942, str. 450–451 (snimka 226) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Predslovlje. Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti, Oče svemogući, vjećni Bože, po Kristu, Gospodinu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i . blaženi Serafini zadružnim klicanjem zajedno slave. Zapovjedi, molimo, da se i naši glasovi združe s njihovima, smjernim ispovijedanjem govoreći:","knRef":"Kniewald 1942, str. 758–759 (snimka 380) (OCR)"},"d76f89b9ab1556d0":{"t":"Mt 19, 28 i 29\nZaista vam kažem da ćete vi koji ste ostavili sve i pošli za mnom primiti stostruko i baštiniti život vječni.","kn":"(Mt. 19, 28, 29). Zaista vam kažem, da čete vi, koji ste sve ostavili 1 koji ste pošli za mnom, primiti stoput onoliko i baštinit ćete život vječni.","knRef":"Kniewald 1942, str. 620–621 (snimka 311) (OCR)"},"63bdcd9669e1a0e5":{"t":"<i>Pomolimo se</i>.\nMolimo, svemogući Bože, da nas nebeska hrana koju smo primili zagovorom blaženoga Nikole, tvoga priznavaoca zaštiti od svih protivnosti.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo, svemo'gući Bože, da nas nebeska hrana, koju primismo, zagovorom blaženoga I., priznavaoca Tvoga, zaštiti od svih protivnosti. Po G. n.","knRef":"Kniewald 1942, str. 818–819 (snimka 410) (OCR)"}}});
